(797634, 88469, 13136, '<td valign="top">Interesting pose/composition. Good lighting. Too far away from the object she is putting in her mouth for that part to be really effective.</td>', 'Interesting pose/composition. Good lighting. Too far away from the object she is putting in her mouth for that part to be really effective.', '2004-07-06 11:25:12.000000', NULL, 1),
(797637, 88264, 15891, '<td valign="top">This is a beautiful image but the purple just doesn''t stand out enough for me.</td>', 'This is a beautiful image but the purple just doesn''t stand out enough for me.', '2004-07-06 11:26:14.000000', NULL, 1),
(797638, 88298, 13136, '<td valign="top">I like the angle of the lighting in this shot. The choice of background color against the pale purple works well. Lovely model.</td>', 'I like the angle of the lighting in this shot. The choice of background color against the pale purple works well. Lovely model.', '2004-07-06 11:26:27.000000', NULL, 1),
(797639, 88423, 13136, '<td valign="top">Overly purpled in my opinion.</td>', 'Overly purpled in my opinion.', '2004-07-06 11:26:54.000000', NULL, 1),
(797642, 88398, 13136, '<td valign="top">Almost looks like a palm tree.</td>', 'Almost looks like a palm tree.', '2004-07-06 11:28:44.000000', NULL, 1),
(797644, 88576, 15891, '<td valign="top">Did you get lucky or did you mean to do this? I''m looking forward to end of the challenge so that I can read the comments you hopefully left with this image. I love it. Most photos of fireworks are a little boring to me but this is very eye catching. Nice job! One thing though... you see that little trail of light on the right? I would have cloned that out as it detracts from your image just a little bit.</td>', 'Did you get lucky or did you mean to do this? I''m looking forward to end of the challenge so that I can read the comments you hopefully left with this image. I love it. Most photos of fireworks are a little boring to me but this is very eye catching. Nice job! One thing though... you see that little trail of light on the right? I would have cloned that out as it detracts from your image just a little bit.', '2004-07-06 11:29:19.000000', NULL, 1),
(797646, 88298, 15891, '<td valign="top">The lighting on this image is just beautiful. But her expression doesn''t match the pose.</td>', 'The lighting on this image is just beautiful. But her expression doesn''t match the pose.', '2004-07-06 11:30:54.000000', NULL, 1),
(797647, 88341, 15891, '<td valign="top">Really? It looks more red to me.</td>', 'Really? It looks more red to me.', '2004-07-06 11:31:47.000000', NULL, 1),
(797651, 88133, 15891, '<td valign="top">Mommy, I''m scared!</td>', 'Mommy, I''m scared!', '2004-07-06 11:36:51.000000', NULL, 1),
(797657, 88436, 13136, '<td valign="top">A bit overblown, but I like the set-up.</td>', 'A bit overblown, but I like the set-up.', '2004-07-06 11:45:28.000000', NULL, 1),
(797663, 88573, 16241, '<td valign="top">very unusual, very good</td>', 'very unusual, very good', '2004-07-06 11:53:49.000000', NULL, 1),
(797665, 88417, 16241, '<td valign="top">nice negative spaces</td>', 'nice negative spaces', '2004-07-06 11:55:06.000000', NULL, 1),
(797667, 88298, 16241, '<td valign="top">very professional</td>', 'very professional', '2004-07-06 11:55:59.000000', NULL, 1),
(797687, 88126, 20223, '<td valign="top">Striking</td>', 'Striking', '2004-07-06 12:20:48.000000', NULL, 1),
(797701, 88287, 13136, '<td valign="top">Nice shot. Would have been better if people were looking at the view instead of taking pictures themselves.</td>', 'Nice shot. Would have been better if people were looking at the view instead of taking pictures themselves.', '2004-07-06 12:46:47.000000', NULL, 1),
(797703, 87681, 13136, '<td valign="top">Good idea. I''m not sure I like the blown out top. Otherwise, pretty unique and cool.</td>', 'Good idea. I''m not sure I like the blown out top. Otherwise, pretty unique and cool.', '2004-07-06 12:47:56.000000', NULL, 1),
(797707, 88126, 23873, '<td valign="top">Love the photo, love the title!</td>', 'Love the photo, love the title!', '2004-07-06 12:53:23.000000', NULL, 1),
(797708, 88314, 13136, '<td valign="top">Humor! Thank you for my only laugh so far in this challenge. Good idea. With some of the fruit cut instead of mashed, I might have tried to put a knife handle in the bunch of grapes as if they had used it.</td>', 'Humor! Thank you for my only laugh so far in this challenge. Good idea. With some of the fruit cut instead of mashed, I might have tried to put a knife handle in the bunch of grapes as if they had used it.', '2004-07-06 12:53:26.000000', NULL, 1),
(797711, 88409, 13136, '<td valign="top">Good use of the sky background. Orange lines of the white surface distract a bit.</td>', 'Good use of the sky background. Orange lines of the white surface distract a bit.', '2004-07-06 12:55:17.000000', NULL, 1),
(797738, 88325, 22186, '<td valign="top">very cool! Nice job!</td>', 'very cool! Nice job!', '2004-07-06 13:22:38.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(797853, 88469, 22825, '<td valign="top">Nice idea.  What doesn''t work is that the grape is central to the shot, but doesn''t stand out due to no contrast with it and the background.</td>', 'Nice idea.  What doesn''t work is that the grape is central to the shot, but doesn''t stand out due to no contrast with it and the background.', '2004-07-06 14:24:22.000000', NULL, 1),
(797904, 88209, 12253, '<td valign="top">Fun shot.  My suggestion would be to have eliminated the background,  the wood line in the wall and the dark curve on the left distract from the main subject (as small distractions as these seem, they affect the overall impact.)  You might have even cropped the left side to eliminate the background and her hand, and it might have been a bit stronger without any other manips.</td>', 'Fun shot.  My suggestion would be to have eliminated the background,  the wood line in the wall and the dark curve on the left distract from the main subject (as small distractions as these seem, they affect the overall impact.)  You might have even cropped the left side to eliminate the background and her hand, and it might have been a bit stronger without any other manips.', '2004-07-06 14:50:50.000000', NULL, 1),
(797906, 88411, 12253, '<td valign="top">Nice use of dof</td>', 'Nice use of dof', '2004-07-06 14:51:15.000000', NULL, 1),
(797937, 88350, 22046, '<td valign="top">Dramatic use of color takes this drop picture out of the "another drop" category into the "Wow!" category. The out of focus water around and behind has a silky feel to it giving an elegance to the overall image. I gave this one a 10.</td>', 'Dramatic use of color takes this drop picture out of the "another drop" category into the "Wow!" category. The out of focus water around and behind has a silky feel to it giving an elegance to the overall image. I gave this one a 10.', '2004-07-06 15:06:08.000000', NULL, 1),
(797943, 88126, 22046, '<td valign="top">Looks like a Cosmo o me... yum! Love the idea and the look. On my mac I can see detail in the hand. On the PC it looks like she''s wearing a black glove. Since the hand is so dark I think that having her actually wear a black glove would have been even better. It would offset the purple drink better I think. In any case I love this and gave it a 9,</td>', 'Looks like a Cosmo o me... yum! Love the idea and the look. On my mac I can see detail in the hand. On the PC it looks like she''s wearing a black glove. Since the hand is so dark I think that having her actually wear a black glove would have been even better. It would offset the purple drink better I think. In any case I love this and gave it a 9,', '2004-07-06 15:07:49.000000', NULL, 1),
(797950, 88377, 22046, '<td valign="top">Is it purple? Well... not yet. But it will be when he is finished rubbing her back. I can accept this and give it the 9 it deserves as a creative idea well executed.</td>', 'Is it purple? Well... not yet. But it will be when he is finished rubbing her back. I can accept this and give it the 9 it deserves as a creative idea well executed.', '2004-07-06 15:09:08.000000', NULL, 1),
(797956, 88342, 22046, '<td valign="top">Subtle, subtle, subtls... I love this one. The purple shawl works so well as the only colored item in the image. To me there is a quality of sadness along with the silence and contemplation. Beautifully done. A 10.</td>', 'Subtle, subtle, subtls... I love this one. The purple shawl works so well as the only colored item in the image. To me there is a quality of sadness along with the silence and contemplation. Beautifully done. A 10.', '2004-07-06 15:10:24.000000', NULL, 1),
(797960, 88298, 22046, '<td valign="top">Heather is a beautiful woman and her purple attire shows off her beauty well. I like this take on the idea of purple. I gave this one a 9,</td>', 'Heather is a beautiful woman and her purple attire shows off her beauty well. I like this take on the idea of purple. I gave this one a 9,', '2004-07-06 15:11:15.000000', NULL, 1),
(797964, 88380, 22046, '<td valign="top">Love that the combination of red and blue comes out with purple shadow. So simple and so effective. Beautiful idea, beautifuly done. A 10.</td>', 'Love that the combination of red and blue comes out with purple shadow. So simple and so effective. Beautiful idea, beautifuly done. A 10.', '2004-07-06 15:12:12.000000', NULL, 1),
(797966, 88619, 22046, '<td valign="top">Simple and effective. I love the way the purple and grey highlight different parts of the star. Well conceived and beautifully executed. I call this a 9.</td>', 'Simple and effective. I love the way the purple and grey highlight different parts of the star. Well conceived and beautifully executed. I call this a 9.', '2004-07-06 15:13:12.000000', NULL, 1),
(797970, 88094, 22046, '<td valign="top">Very clever. The white background makes this work perfectly. Cool idea.</td>', 'Very clever. The white background makes this work perfectly. Cool idea.', '2004-07-06 15:14:02.000000', NULL, 1),
(797972, 88357, 22046, '<td valign="top">This is so close to blue rather than purple but I can see a touch of purple in here so it just passes the color test. That over and done with it is absolutely gorgeous. The leaf edge on the left makes it more than just another leaf vein photo. Also the lighting is wonderful. I give this an 8.</td>', 'This is so close to blue rather than purple but I can see a touch of purple in here so it just passes the color test. That over and done with it is absolutely gorgeous. The leaf edge on the left makes it more than just another leaf vein photo. Also the lighting is wonderful. I give this an 8.', '2004-07-06 15:15:29.000000', NULL, 1),
(797974, 88613, 22046, '<td valign="top">What a great house. I would love to live here. The colors are fabulous. (I almost think I may have seen this house in an architectural magazine...?) Anyhow it''s a great take on the theme and an 8 in my book.</td>', 'What a great house. I would love to live here. The colors are fabulous. (I almost think I may have seen this house in an architectural magazine...?) Anyhow it''s a great take on the theme and an 8 in my book.', '2004-07-06 15:17:04.000000', NULL, 1),
(797976, 88429, 22046, '<td valign="top">Simple and effective. Love all the  swirling colors and patterns in the bubbles.</td>', 'Simple and effective. Love all the  swirling colors and patterns in the bubbles.', '2004-07-06 15:18:05.000000', NULL, 1),
(797979, 86980, 22046, '<td valign="top">The purple lighting really works well here. I also like the simple lines of her face and dress. Nice one!</td>', 'The purple lighting really works well here. I also like the simple lines of her face and dress. Nice one!', '2004-07-06 15:19:11.000000', NULL, 1),
(797984, 88417, 22046, '<td valign="top">Isn''t red cabbage beautiful! I almost used the same thing for my purple image... I like the high contrast of the dark shadow and the highlighted leaves. Also love all the different shades of purple.</td>', 'Isn''t red cabbage beautiful! I almost used the same thing for my purple image... I like the high contrast of the dark shadow and the highlighted leaves. Also love all the different shades of purple.', '2004-07-06 15:20:22.000000', NULL, 1),
(797986, 86981, 22046, '<td valign="top">Clever idea and nifty title. I''m guessing he has gloves to simplify the hands and hide any human blemishes. Good plan. This makes them appear more mysterious and keeps the image simpler. I like this very much.</td>', 'Clever idea and nifty title. I''m guessing he has gloves to simplify the hands and hide any human blemishes. Good plan. This makes them appear more mysterious and keeps the image simpler. I like this very much.', '2004-07-06 15:22:05.000000', NULL, 1),
(797987, 88436, 22046, '<td valign="top">High key works again. I don''t know if you are the same photographer who usually does things in high key but if you are it works. (Even if you aren''t it works.) I love the purple hair.</td>', 'High key works again. I don''t know if you are the same photographer who usually does things in high key but if you are it works. (Even if you aren''t it works.) I love the purple hair.', '2004-07-06 15:23:09.000000', NULL, 1),
(797991, 86762, 22046, '<td valign="top">Not just another flower picture but a sharply focused beautifuly cropped purple flower picture. Love it.</td>', 'Not just another flower picture but a sharply focused beautifuly cropped purple flower picture. Love it.', '2004-07-06 15:23:54.000000', NULL, 1),
(797993, 87509, 22046, '<td valign="top">Cool idea. I think it might be even better with greater depth of field. But I love this take on purple.</td>', 'Cool idea. I think it might be even better with greater depth of field. But I love this take on purple.', '2004-07-06 15:25:00.000000', NULL, 1),
(797995, 88314, 22046, '<td valign="top">Cracks me up. Cool idea. Love all that mashed fruit and the intact grapes.</td>', 'Cracks me up. Cool idea. Love all that mashed fruit and the intact grapes.', '2004-07-06 15:26:23.000000', NULL, 1),
(797999, 88525, 22046, '<td valign="top">Great sunset and interesting composition... it looks like the boy is walking on water...</td>', 'Great sunset and interesting composition... it looks like the boy is walking on water...', '2004-07-06 15:27:25.000000', NULL, 1),
(798002, 88209, 22046, '<td valign="top">Cute kid with an amazing expression on her face.</td>', 'Cute kid with an amazing expression on her face.', '2004-07-06 15:28:35.000000', NULL, 1),
(798004, 88075, 22046, '<td valign="top">This one works for me. I like the focus on her hand and the expression of defeat on her face.</td>', 'This one works for me. I like the focus on her hand and the expression of defeat on her face.', '2004-07-06 15:29:31.000000', NULL, 1),
(798006, 88133, 22046, '<td valign="top">Wow! This really pops (no pun intended). Great idea. On my mac I can see details in the face and that works well for me, better than it looked when I first looked on my PC. I''m upping the rating I gave this to a 9.</td>', 'Wow! This really pops (no pun intended). Great idea. On my mac I can see details in the face and that works well for me, better than it looked when I first looked on my PC. I''m upping the rating I gave this to a 9.', '2004-07-06 15:31:08.000000', NULL, 1),
(798009, 87976, 22046, '<td valign="top">You do well to call attention to the leaf  in your title. One of the best things about this is the bit of purple that shows through the translucent leaf. The lighting here  is perfect. A beautiful image.</td>', 'You do well to call attention to the leaf  in your title. One of the best things about this is the bit of purple that shows through the translucent leaf. The lighting here  is perfect. A beautiful image.', '2004-07-06 15:32:19.000000', NULL, 1),
(798011, 88301, 22046, '<td valign="top">The more I look the more I like it. Simple. Great colors. Way cool.</td>', 'The more I look the more I like it. Simple. Great colors. Way cool.', '2004-07-06 15:33:13.000000', NULL, 1),
(798017, 86416, 22046, '<td valign="top">Very clever idea. One idea to make it work even better would be to swirl the two paints together as they approach the candies rather than leaving two separate paths. You could also put the candies out so the simpler looking ones were closer to the paints and  hte more complex ones were further away so as to continue the blending outwordly... This is not to say I don''t like what you have here. I do.</td>', 'Very clever idea. One idea to make it work even better would be to swirl the two paints together as they approach the candies rather than leaving two separate paths. You could also put the candies out so the simpler looking ones were closer to the paints and  hte more complex ones were further away so as to continue the blending outwordly... This is not to say I don''t like what you have here. I do.', '2004-07-06 15:36:17.000000', NULL, 1),
(798020, 88614, 22083, '<td valign="top">While the photo is not that great, I do like your attitude. Hope you get better soon!</td>', 'While the photo is not that great, I do like your attitude. Hope you get better soon!', '2004-07-06 15:40:13.000000', NULL, 1),
(798027, 88262, 22083, '<td valign="top">I like the composition and the background, but think you should have picked a different time of day or shaded the flower to block some of the harsh light</td>', 'I like the composition and the background, but think you should have picked a different time of day or shaded the flower to block some of the harsh light', '2004-07-06 15:45:38.000000', NULL, 1),
(798032, 87305, 22083, '<td valign="top">That is almost scary, had I seen this when I was way younger I might have never tried them  :) That top shroom almost looks evil.  GREAT JOB!</td>', 'That is almost scary, had I seen this when I was way younger I might have never tried them  :) That top shroom almost looks evil.  GREAT JOB!', '2004-07-06 15:48:04.000000', NULL, 1),
(798039, 88495, 22083, '<td valign="top">Sorry but your picture came in right behind the purple mushroom, I had to laugh because the person looking at the light made me think he/she had tried those purple mushroomz</td>', 'Sorry but your picture came in right behind the purple mushroom, I had to laugh because the person looking at the light made me think he/she had tried those purple mushroomz', '2004-07-06 15:53:21.000000', NULL, 1),
(798048, 88038, 22083, '<td valign="top">Sorry to say but on my monitor your main color is blue, pretty blue but blue</td>', 'Sorry to say but on my monitor your main color is blue, pretty blue but blue', '2004-07-06 16:04:56.000000', NULL, 1),
(798051, 88194, 22083, '<td valign="top">If that bee had any purple on him I would have given you a 10 that is a great shot. but I think the main subject since its so perfect is the bee, I really dont even notice that the flower is purple</td>', 'If that bee had any purple on him I would have given you a 10 that is a great shot. but I think the main subject since its so perfect is the bee, I really dont even notice that the flower is purple', '2004-07-06 16:09:18.000000', NULL, 1),
(798054, 88422, 22083, '<td valign="top">makes me want to reah out and pick it off my computer screen, Great DOF and the contrast is outstanding. You get my vote for #1</td>', 'makes me want to reah out and pick it off my computer screen, Great DOF and the contrast is outstanding. You get my vote for #1', '2004-07-06 16:13:05.000000', NULL, 1),
(798061, 88383, 22083, '<td valign="top">Please tell me your a pro... Great shot!</td>', 'Please tell me your a pro... Great shot!', '2004-07-06 16:18:22.000000', NULL, 1),
(798068, 88561, 22083, '<td valign="top">Very Clever, alas still no purple...yet!</td>', 'Very Clever, alas still no purple...yet!', '2004-07-06 16:22:48.000000', NULL, 1),
(798072, 88524, 22083, '<td valign="top">wow for some reason this challege sure congers up some old dazes ooppss I ment days...</td>', 'wow for some reason this challege sure congers up some old dazes ooppss I ment days...', '2004-07-06 16:25:11.000000', NULL, 1),
(798088, 88208, 22083, '<td valign="top">First let me appologize and also to say that I did not enter this contest. I am confused by some of the terminology in the rules but I think that this picture is of art work and by my interpretation of the rules it is not usable. I did want to click on recommend this for disqualification but I do not know what all the reprocussions are so will just leve you with this comment instead. Not a bad pic at all but tell me what you think the art work rule means to you so maybe I might have a better understanding.</td>', 'First let me appologize and also to say that I did not enter this contest. I am confused by some of the terminology in the rules but I think that this picture is of art work and by my interpretation of the rules it is not usable. I did want to click on recommend this for disqualification but I do not know what all the reprocussions are so will just leve you with this comment instead. Not a bad pic at all but tell me what you think the art work rule means to you so maybe I might have a better understanding.', '2004-07-06 16:35:19.000000', NULL, 1),
(798091, 88358, 22083, '<td valign="top">is it morano?</td>', 'is it morano?', '2004-07-06 16:36:56.000000', NULL, 1),
(798196, 88342, 16703, '<td valign="top">a 10 no question about it</td>', 'a 10 no question about it', '2004-07-06 17:52:56.000000', NULL, 1),
(798268, 88214, 13044, '<td valign="top">Where''s the purple in this one?</td>', 'Where''s the purple in this one?', '2004-07-06 18:34:38.000000', NULL, 1),
(798324, 88613, 20066, '<td valign="top">I think it would have been better if you cut off all edges.  The tree in the foreground is disturbing me somehow.  But perhaps it is just as you wanted it to be.</td>', 'I think it would have been better if you cut off all edges.  The tree in the foreground is disturbing me somehow.  But perhaps it is just as you wanted it to be.', '2004-07-06 19:03:59.000000', NULL, 1),
(798325, 88325, 20066, '<td valign="top">I''ve never seen so purple fly!</td>', 'I''ve never seen so purple fly!', '2004-07-06 19:04:24.000000', NULL, 1),
(798335, 88374, 22385, '<td valign="top">Wow, that is pretty funny!  I wouldn''t pick this one to win the challenge, but I do think it is in great focus and evokes some laughter in me.</td>', 'Wow, that is pretty funny!  I wouldn''t pick this one to win the challenge, but I do think it is in great focus and evokes some laughter in me.', '2004-07-06 19:11:49.000000', NULL, 1),
(798338, 88469, 22385, '<td valign="top">If this were just a tad brighter, I''d rate it higher.  I do like the composition of this picture, though.</td>', 'If this were just a tad brighter, I''d rate it higher.  I do like the composition of this picture, though.', '2004-07-06 19:13:26.000000', NULL, 1),
(798343, 88561, 22385, '<td valign="top">How did the result actually turn out?  I''d be curious to see how it looked.  And is this food coloring of some sort or perhaps smoke?  Nice effort, very simple look.</td>', 'How did the result actually turn out?  I''d be curious to see how it looked.  And is this food coloring of some sort or perhaps smoke?  Nice effort, very simple look.', '2004-07-06 19:15:22.000000', NULL, 1),
(798344, 88614, 22385, '<td valign="top">Ouch... though the purple doesn''t show through enough on this photo (by no means would I suggest you go beating yourself up to deepen the purple!).  Granted, this is very creative!  I just wouldn''t pick it to win the challenge.</td>', 'Ouch... though the purple doesn''t show through enough on this photo (by no means would I suggest you go beating yourself up to deepen the purple!).  Granted, this is very creative!  I just wouldn''t pick it to win the challenge.', '2004-07-06 19:17:17.000000', NULL, 1),
(798347, 88209, 22385, '<td valign="top">LOL... great subject.  Was this a true candid shot or was this done specifically for this contest?  Either way, I really get a kick out of this photo.  Nice job!  I''d give it an 8!</td>', 'LOL... great subject.  Was this a true candid shot or was this done specifically for this contest?  Either way, I really get a kick out of this photo.  Nice job!  I''d give it an 8!', '2004-07-06 19:19:03.000000', NULL, 1),
(798350, 87520, 22385, '<td valign="top">Soft focus - is this what you were going for?  I think it would be a better photo if it was a little sharper on the three purple pills.  I like the concept, though!</td>', 'Soft focus - is this what you were going for?  I think it would be a better photo if it was a little sharper on the three purple pills.  I like the concept, though!', '2004-07-06 19:20:37.000000', NULL, 1),
(798351, 88366, 22385, '<td valign="top">I really enjoy this picture, and I''m not quite sure why!  The model seems to have some "spunk."  Good pose, and I like the use of purple.</td>', 'I really enjoy this picture, and I''m not quite sure why!  The model seems to have some "spunk."  Good pose, and I like the use of purple.', '2004-07-06 19:22:02.000000', NULL, 1),
(798355, 88258, 22385, '<td valign="top">Wow!  This picture just blares out purple!  For the most part, I like this photo.  However, I think it would have been better without the tag on the object in the foreground.  The purple on the wall seems a tad oversaturated, and I wish the carpet provided more contrast.  Again, though -  I really like the concept of the photo overall!</td>', 'Wow!  This picture just blares out purple!  For the most part, I like this photo.  However, I think it would have been better without the tag on the object in the foreground.  The purple on the wall seems a tad oversaturated, and I wish the carpet provided more contrast.  Again, though -  I really like the concept of the photo overall!', '2004-07-06 19:25:01.000000', NULL, 1),
(798357, 88377, 9411, '<td valign="top">hmm,  red and blue do make purple, so the suggestion is there.  I like the "wet" feel of it all.  My personal taste is entering in here, I find the crop not as dynamic as it could be, (and this is just my opinion). I moved the window over to do an alternate "crop" and find that if more of the arm was not there the had would really stand out and the cuve of the body would become more of an element in the image.  I have a feeling you may not be doing well in this challenge.  Since you have really captured the literal sense of "suggestion"..   8</td>', 'hmm,  red and blue do make purple, so the suggestion is there.  I like the "wet" feel of it all.  My personal taste is entering in here, I find the crop not as dynamic as it could be, (and this is just my opinion). I moved the window over to do an alternate "crop" and find that if more of the arm was not there the had would really stand out and the cuve of the body would become more of an element in the image.  I have a feeling you may not be doing well in this challenge.  Since you have really captured the literal sense of "suggestion"..   8', '2004-07-06 19:26:50.000000', NULL, 1),
(798384, 88342, 9411, '<td valign="top">This is an absolutely stunning image. There is drama, tesnsion and multiple levels of interest. Your choice of placement for the model is perfect.  I really see no where to make a comment for improvement.  BRAVO  10</td>', 'This is an absolutely stunning image. There is drama, tesnsion and multiple levels of interest. Your choice of placement for the model is perfect.  I really see no where to make a comment for improvement.  BRAVO  10', '2004-07-06 19:42:13.000000', NULL, 1),
(798388, 88573, 9411, '<td valign="top">Stunning floral, ala O''Keefe.  Love the rich deep tones, composition and dof.  It is almost abstract, while retaining just enough information to let the viewer appreciate the actuallity of the components.   nicely done  10</td>', 'Stunning floral, ala O''Keefe.  Love the rich deep tones, composition and dof.  It is almost abstract, while retaining just enough information to let the viewer appreciate the actuallity of the components.   nicely done  10', '2004-07-06 19:43:40.000000', NULL, 1),
(798391, 88298, 9411, '<td valign="top">Stunning portrait.. The light is excellent, the shadows add another dimension and just a bit of mystery. nicely done. 9</td>', 'Stunning portrait.. The light is excellent, the shadows add another dimension and just a bit of mystery. nicely done. 9', '2004-07-06 19:44:30.000000', NULL, 1),
(798393, 88390, 9411, '<td valign="top">Fascinating image. So many engaging elements to appreciate. The purple toning works very well and reminds me of some the colour washes we saw in glossy magazines in the 59''s and 60''s.. nicely done.</td>', 'Fascinating image. So many engaging elements to appreciate. The purple toning works very well and reminds me of some the colour washes we saw in glossy magazines in the 59''s and 60''s.. nicely done.', '2004-07-06 19:45:32.000000', NULL, 1),
(798415, 88126, 9411, '<td valign="top">Excellent concept. I love the composition, the lime is a very nice touch. The only thing that, in my opion, could be just a bit better is the hand either being competely shadowed (ie black) or with a bit more detail.  It just feels to me that it is inbetween somewhere, and not entirely as it should be.  Still a very nice image.</td>', 'Excellent concept. I love the composition, the lime is a very nice touch. The only thing that, in my opion, could be just a bit better is the hand either being competely shadowed (ie black) or with a bit more detail.  It just feels to me that it is inbetween somewhere, and not entirely as it should be.  Still a very nice image.', '2004-07-06 19:54:02.000000', NULL, 1),
(798438, 87016, 22385, '<td valign="top">I really love the shades of purple in this picture.  It''s very abstract, and the lighting is beautiful.  This would actually be one of my top picks for this challenge.  I''d give this a 9.</td>', 'I really love the shades of purple in this picture.  It''s very abstract, and the lighting is beautiful.  This would actually be one of my top picks for this challenge.  I''d give this a 9.', '2004-07-06 20:10:02.000000', NULL, 1),
