(803871, 88262, 8367, '<td valign="top">Beautiful background and great composition.</td>', 'Beautiful background and great composition.', '2004-07-09 14:01:15.000000', NULL, 1),
(803885, 88383, 8367, '<td valign="top">Great photo with very rich color.The black background gives it an elegant look. (The greenery on the right appears (to me)  to be a bit cut-off. Doesn''t quite flow right.)</td>', 'Great photo with very rich color.The black background gives it an elegant look. (The greenery on the right appears (to me)  to be a bit cut-off. Doesn''t quite flow right.)', '2004-07-09 14:13:01.000000', NULL, 1),
(803912, 88342, 6073, '<td valign="top">Good pic, but the color purple is not the subject.  The women is the subject, and the title suggests that she reflecting is silence.  This doesn''t have too much to do with the color purple.<br/> <br/>Good portrait overall, but the image has a bit of digital noise on my monitor.  I like the frame.</td>', 'Good pic, but the color purple is not the subject.  The women is the subject, and the title suggests that she reflecting is silence.  This doesn''t have too much to do with the color purple. Good portrait overall, but the image has a bit of digital noise on my monitor.  I like the frame.', '2004-07-09 14:43:52.000000', NULL, 1),
(803913, 87963, 6073, '<td valign="top">I don''t see a single focal plane.  I think I get the idea though, but the image itself does not strongly support the message.</td>', 'I don''t see a single focal plane.  I think I get the idea though, but the image itself does not strongly support the message.', '2004-07-09 14:44:48.000000', NULL, 1),
