(804114, 88298, 6073, '<td valign="top">Excellent all the way around!</td>', 'Excellent all the way around!', '2004-07-09 17:55:52.000000', NULL, 1),
(804168, 86420, 19608, '<td valign="top">You havre a really nice desat - in a very interesting composition.  The spider is a perfect accesnt.  Make it better by cropping off the bright white traingle left top.</td>', 'You havre a really nice desat - in a very interesting composition.  The spider is a perfect accesnt.  Make it better by cropping off the bright white traingle left top.', '2004-07-09 18:46:08.000000', NULL, 1),
(804171, 88612, 19608, '<td valign="top">I really like your green and red against the purple draped background - they go well together.  Somehow the flower seems lifeless and unnatural hanging upside down.  Not sure I like that.<br/><br/><i>Message edited by author 2004-07-12 11:59:18.</i></td>', 'I really like your green and red against the purple draped background - they go well together.  Somehow the flower seems lifeless and unnatural hanging upside down.  Not sure I like that.', '2004-07-09 18:48:14.000000', '2004-07-12 12:59:18.000000', 1),
(804174, 87305, 19608, '<td valign="top">Good nature shoit abiet way unusual.</td>', 'Good nature shoit abiet way unusual.', '2004-07-09 18:48:51.000000', NULL, 1),
(804177, 88575, 19608, '<td valign="top">A very nice macro of a pansy or jumping jack?  Great colors - well saturated.  Black background was a perfect choice.</td>', 'A very nice macro of a pansy or jumping jack?  Great colors - well saturated.  Black background was a perfect choice.', '2004-07-09 18:49:59.000000', NULL, 1),
(804180, 88306, 19608, '<td valign="top">An exceptional capture which I know is very difficult - or lucky!  The only problem I have is mine - not yours.  That is this technique has been used quite often - so it''s become rather mundane.</td>', 'An exceptional capture which I know is very difficult - or lucky!  The only problem I have is mine - not yours.  That is this technique has been used quite often - so it''s become rather mundane.', '2004-07-09 18:51:52.000000', NULL, 1),
(804181, 88174, 2764, '<td valign="top">Beautiful, beautiful, beautiful - such a nicely balanced photo between the flowers and the smile.</td>', 'Beautiful, beautiful, beautiful - such a nicely balanced photo between the flowers and the smile.', '2004-07-09 18:52:29.000000', NULL, 1),
(804182, 88317, 19608, '<td valign="top">A very interesting image - and quite original.  Toss the border - or at least remove the purple.</td>', 'A very interesting image - and quite original.  Toss the border - or at least remove the purple.', '2004-07-09 18:52:55.000000', NULL, 1),
(804185, 88170, 19608, '<td valign="top">It''s definitely purple and original.  Somehow - it just doesn''t grab me - can''t quite understand why.</td>', 'It''s definitely purple and original.  Somehow - it just doesn''t grab me - can''t quite understand why.', '2004-07-09 18:54:07.000000', NULL, 1),
(804186, 88390, 19608, '<td valign="top">A very unusual group portraint to say the least.  Looks like it could have been taken in the 50''s or so.</td>', 'A very unusual group portraint to say the least.  Looks like it could have been taken in the 50''s or so.', '2004-07-09 18:55:22.000000', NULL, 1),
(804189, 88399, 19608, '<td valign="top">An unusual angle and some very purple''s here and there.  Overall it seems a bit busy for me - I think a better image would include only a boat or two... For example, I''d  like the purple boat in the bottom left corner along with the lilac one above it.</td>', 'An unusual angle and some very purple''s here and there.  Overall it seems a bit busy for me - I think a better image would include only a boat or two... For example, I''d  like the purple boat in the bottom left corner along with the lilac one above it.', '2004-07-09 18:58:47.000000', NULL, 1),
(804190, 88399, 2764, '<td valign="top">odd. but VERY effective - with the colors being so strange, it becomes and abstract pattern focused around the guy -</td>', 'odd. but VERY effective - with the colors being so strange, it becomes and abstract pattern focused around the guy -', '2004-07-09 18:58:55.000000', NULL, 1),
