(805523, 88440, 22734, '<td valign="top">Very good work and great attention to detail. Of course, the viewer wants the gold artifact sharper, but you have ourdone yourself with the eye make-up. Great image.</td>', 'Very good work and great attention to detail. Of course, the viewer wants the gold artifact sharper, but you have ourdone yourself with the eye make-up. Great image.', '2004-07-11 01:35:08.000000', NULL, 1),
(805524, 87881, 9668, '<td valign="top">Fits the topic. Small, interesing black line on top. If your subject was further from the background, the background would be less distracing. Subject is good off center, vertical rule of thirds.</td>', 'Fits the topic. Small, interesing black line on top. If your subject was further from the background, the background would be less distracing. Subject is good off center, vertical rule of thirds.', '2004-07-11 01:35:14.000000', NULL, 1),
(805528, 86420, 9668, '<td valign="top">First I looked at it and thought, "that''s a different perspective." Then I was like whoa! spider! Cool. Window in background is annoying but is blurred well by your DOF. Inspired by the selective desaturation challenge?</td>', 'First I looked at it and thought, "that''s a different perspective." Then I was like whoa! spider! Cool. Window in background is annoying but is blurred well by your DOF. Inspired by the selective desaturation challenge?', '2004-07-11 01:36:35.000000', NULL, 1),
(805529, 88613, 9668, '<td valign="top">Purple is in it, but it stands out as much as the red or yellow. Would of been funny to have somebody peeking out of the window. I like the landscape in the background.</td>', 'Purple is in it, but it stands out as much as the red or yellow. Would of been funny to have somebody peeking out of the window. I like the landscape in the background.', '2004-07-11 01:39:29.000000', NULL, 1),
